function Production({ plan, openImpact }) {
  return (
    <>
      <PageHead title="Production" subtitle="What changed versus plan?">
        <Badge>Expected {fmtT(plan.expected_total_t)}</Badge>
        <Badge>Actual {fmtT(plan.actual_total_t)}</Badge>
        <Badge variant="hot">Variance {signedT(plan.production_variance_t)}</Badge>
      </PageHead>
      <Card>
        <CardTitle>Production snapshot</CardTitle>
        <div className="warning-facts">
          {Object.entries(plan.actual_by_segment_t).map(([segment, value]) => (
            <Badge key={segment}>
              {segment}: actual {fmtT(value)}
            </Badge>
          ))}
          <Badge variant="hot">
            Segment A below plan by {Math.abs(plan.segment_variance_t.A).toFixed(1)} t
          </Badge>
        </div>
      </Card>
      <Card style={{ marginTop: 14 }}>
        <CardTitle>What matters today</CardTitle>
        <div className="warning-facts">
          {plan.production_alerts.map((alert, index) => {
            const impact = alert.farm_id ? `${alert.farm_id}:${alert.segment}` : "";
            return (
              <Button
                key={`${alert.label}-${index}`}
                variant="outline"
                className={cn("ui-badge", alert.severity === "important" && "ui-badge-hot")}
                onClick={() => impact && openImpact(impact)}
              >
                {alert.label} | {alert.detail}
              </Button>
            );
          })}
        </div>
      </Card>
      <TableWrap style={{ marginTop: 14 }}>
        <Table>
          <thead>
            <tr>
              <th>Farm</th>
              <th className="num">Expected Capacity</th>
              <th className="num">Actual Total</th>
              <th className="num">Variance</th>
              {SEGMENTS.map((segment) => (
                <FarmSegmentHead key={segment} segment={segment} />
              ))}
              <th className="num">Local Residual</th>
            </tr>
          </thead>
          <tbody>
            {plan.farms.map((farm) => (
              <tr key={farm.farm_id}>
                <td>
                  <strong>{farm.farm_id}</strong>
                  <br />
                  <span className="muted">{farm.farm_name}</span>
                </td>
                <td className="num">{fmtT(farm.expected_capacity_t)}</td>
                <td className="num">{fmtT(farm.actual_total_t)}</td>
                <td className={cn("num", cssVar(farm.variance_t))}>{signedT(farm.variance_t)}</td>
                {SEGMENTS.map((segment) => {
                  const row = farm.segments[segment];
                  return (
                    <FarmSegmentCells
                      key={`${farm.farm_id}-${segment}`}
                      farmId={farm.farm_id}
                      segment={segment}
                      row={row}
                      openImpact={openImpact}
                    />
                  );
                })}
                <td className={cn("num", farm.local_residual_t > 0 && "neg")}>
                  {fmtT(farm.local_residual_t)}
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      </TableWrap>
    </>
  );
}

function FarmSegmentHead({ segment }) {
  return (
    <>
      <th className="num">Expected {segment}</th>
      <th className="num">Actual {segment}</th>
      <th className="num">{segment} Var</th>
    </>
  );
}

function FarmSegmentCells({ farmId, segment, row, openImpact }) {
  return (
    <>
      <td className="num">{fmtT(row.expected_t)}</td>
      <td className="num">{fmtT(row.actual_t)}</td>
      <td className="num">
        <button
          className={cn("click-var", cssVar(row.variance_t))}
          onClick={() => openImpact(`${farmId}:${segment}`)}
          type="button"
        >
          {signedT(row.variance_t)}
        </button>
      </td>
    </>
  );
}

