function Allocations({ plan, filters, setFilters }) {
  const farms = useMemo(
    () =>
      [
        ...new Set(
          plan.allocations.map((row) => row.farm_id).concat(plan.local_residuals.map((row) => row.farm_id)),
        ),
      ].sort(),
    [plan],
  );
  const clients = useMemo(
    () => [...new Set(plan.allocations.map((row) => row.client_id))].sort(),
    [plan],
  );
  const rows = plan.allocations.filter(
    (row) =>
      (filters.farm === "ALL" || row.farm_id === filters.farm) &&
      (filters.segment === "ALL" || row.segment === filters.segment) &&
      (filters.client === "ALL" || row.client_id === filters.client) &&
      (filters.upgrade === "ALL" || row.quality_upgrade === filters.upgrade),
  );

  function updateFilter(name, value) {
    setFilters((current) => ({ ...current, [name]: value }));
  }

  return (
    <>
      <PageHead title="Allocations" subtitle="Which farm and segment serves which client?">
        <Badge>{fmtT(plan.exported_t)} exported</Badge>
        <Badge variant="hot">{fmtT(plan.local_t)} local residual</Badge>
      </PageHead>
      <div className="toolbar">
        <FilterSelect label="Farm" value={filters.farm} options={farms} onChange={(value) => updateFilter("farm", value)} />
        <FilterSelect label="Segment" value={filters.segment} options={SEGMENTS} onChange={(value) => updateFilter("segment", value)} />
        <FilterSelect label="Client" value={filters.client} options={clients} onChange={(value) => updateFilter("client", value)} />
        <FilterSelect label="Exact / Upgraded" value={filters.upgrade} options={["EXACT", "UPGRADED"]} onChange={(value) => updateFilter("upgrade", value)} />
      </div>
      <Card>
        <CardTitle>Export allocations</CardTitle>
        <TableWrap style={{ marginTop: 12 }}>
          <Table>
            <thead>
              <tr>
                <th>Farm ID</th>
                <th>Segment</th>
                <th>Client ID</th>
                <th className="num">Tonnes</th>
                <th>Quality Upgrade</th>
                <th className="num">Export Price</th>
                <th className="num">Export Revenue</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row, index) => (
                <tr key={`${row.farm_id}-${row.segment}-${row.client_id}-${index}`}>
                  <td>{row.farm_id}</td>
                  <td>{row.segment}</td>
                  <td>{row.client_id}</td>
                  <td className="num">{fmtT(row.tonnes)}</td>
                  <td>{row.quality_upgrade}</td>
                  <td className="num">{fmtEur(row.export_price_per_t_eur)}</td>
                  <td className="num">{fmtEur(row.export_revenue_eur)}</td>
                </tr>
              ))}
            </tbody>
          </Table>
        </TableWrap>
      </Card>
      <Card style={{ marginTop: 14 }}>
        <CardTitle>Local residual</CardTitle>
        <TableWrap style={{ marginTop: 12 }}>
          <Table>
            <thead>
              <tr>
                <th>Farm</th>
                <th>Segment</th>
                <th className="num">Tonnes</th>
                <th className="num">Reference price</th>
                <th className="num">Local value</th>
              </tr>
            </thead>
            <tbody>
              {plan.local_residuals.map((row, index) => (
                <tr key={`${row.farm_id}-${row.segment}-${index}`}>
                  <td>{row.farm_id}</td>
                  <td>{row.segment}</td>
                  <td className="num neg">{fmtT(row.tonnes)}</td>
                  <td className="num">{fmtEur(row.reference_price_per_t_eur)}</td>
                  <td className="num">{fmtEur(row.local_value_eur)}</td>
                </tr>
              ))}
            </tbody>
          </Table>
        </TableWrap>
      </Card>
    </>
  );
}

function FilterSelect({ label, value, options, onChange }) {
  return (
    <label>
      <span className="eyebrow">{label}</span>
      <Select value={value} onChange={(event) => onChange(event.target.value)}>
        <option value="ALL">All</option>
        {options.map((option) => (
          <option key={option} value={option}>
            {option}
          </option>
        ))}
      </Select>
    </label>
  );
}

function AssistantView({
  assistant,
  customQuestion,
  setCustomQuestion,
  askAssistant,
}) {
  const response = assistant.answer;
  return (
    <>
      <PageHead title="Planning Assistant" subtitle="Grounded explanation of the calculated plan" />
      <section className="assistant-shell">
        <Card>
          <CardTitle>Suggested questions</CardTitle>
          <div className="question-list">
            {QUESTIONS.map((question) => (
              <Button
                key={question}
                variant="secondary"
                onClick={() => askAssistant(question)}
                style={{ height: "auto", minHeight: 44, justifyContent: "flex-start", textAlign: "left" }}
              >
                <Icon name="help" />
                {question}
              </Button>
            ))}
          </div>
          <div className="toolbar">
            <Input
              value={customQuestion}
              onChange={(event) => setCustomQuestion(event.target.value)}
              placeholder="Ask from current planning data"
            />
            <Button variant="secondary" onClick={() => askAssistant(customQuestion)}>
              <Icon name="send" />
              Ask
            </Button>
          </div>
        </Card>
        <Card className="answer">
          {assistant.loading ? <CardTitle>Thinking from calculated data...</CardTitle> : null}
          {assistant.error ? (
            <div className="error-state" style={{ margin: 0 }}>
              <h2>{assistant.error.title}</h2>
              <p>{assistant.error.message}</p>
              <Button onClick={() => askAssistant(assistant.lastQuestion || QUESTIONS[0])}>
                <Icon name="replay" />
                Retry
              </Button>
            </div>
          ) : null}
          {response ? (
            <>
              <div>
                <span className="eyebrow">{response.provider_state || "Deterministic summary"}</span>
                <h2>{response.mode === "deterministic" ? "Deterministic summary" : "Assistant response"}</h2>
              </div>
              <p>{response.answer}</p>
              <div className="warning-facts">
                {(response.evidence || []).map((item) => (
                  <Badge
                    key={item}
                    variant={
                      String(item).startsWith("C0") || String(item).includes("Segment A")
                        ? "hot"
                        : "default"
                    }
                  >
                    {item}
                  </Badge>
                ))}
              </div>
            </>
          ) : null}
          {!assistant.loading && !assistant.error && !response ? (
            <p className="subtitle">
              No AI provider configured. Deterministic summaries are generated from server-calculated results.
            </p>
          ) : null}
        </Card>
      </section>
    </>
  );
}

function ImpactDrawer({ item }) {
  return (
    <div className="stack">
      <div className="mini-grid">
        <div className="mini">
          <span>Farm / segment gap</span>
          <strong className={cssVar(item.variance_t)}>{signedT(item.variance_t)}</strong>
        </div>
        <div className="mini">
          <span>Available compatible supply</span>
          <strong>{fmtT(item.actual_t)}</strong>
        </div>
        <div className="mini">
          <span>Allocated volume</span>
          <strong>{fmtT(item.allocated_t)}</strong>
        </div>
        <div className="mini">
          <span>Local residual</span>
          <strong className={item.local_t > 0 ? "neg" : ""}>{fmtT(item.local_t)}</strong>
        </div>
      </div>
      <Card>
        <h3>Affected client(s)</h3>
        <div className="warning-facts">
          {item.affected_clients.length ? (
            item.affected_clients.map((client) => (
              <Badge key={client.client_id} variant="hot">
                {client.client_id} | allocated {fmtT(client.allocated_t)} | remaining{" "}
                {fmtT(client.remaining_t)} | {client.shortage_reason}
              </Badge>
            ))
          ) : (
            <Badge>No at-risk client directly tied to this farm segment</Badge>
          )}
        </div>
      </Card>
      <Card>
        <h3>Trace allocations</h3>
        <div className="warning-facts">
          {item.allocations.length ? (
            item.allocations.map((allocation, index) => (
              <Badge key={`${allocation.client_id}-${index}`}>
                {allocation.client_id} | {fmtT(allocation.tonnes)} | {allocation.quality_upgrade}
              </Badge>
            ))
          ) : (
            <Badge>No export allocation</Badge>
          )}
        </div>
      </Card>
    </div>
  );
}
